<script setup lang="ts">
import { onMounted,onUnmounted,reactive,ref } from 'vue'
import { useRoute } from 'vue-router'
import { api,apiBlob,useLoad,useCommand,money,time,PageHeader,Feedback,StatusBadge,type Aftersale,type Materials } from '@tradeflow/ui'
import { pathNo,usePoll } from '../state'
const no=String(useRoute().params.no),url=`/aftersales/${pathNo(no)}`
const load=useLoad<Aftersale>(s=>api(url,{signal:s})),materials=useLoad<Materials>(s=>api(`${url}/materials`,{signal:s})),command=useCommand(`user-aftersale:${no}`),shipment=reactive({carrier:'',trackingNo:''}),notice=ref(''),error=ref(''),images=ref<Record<string,string>>({}),imageBusy=ref('')
let alive=true;const imageController=new AbortController()
const allowed=(a:string)=>load.data.value?.allowedActions?.includes(a)
const poll=usePoll(async signal=>{const result=await api<Aftersale>(url,{signal});if(signal.aborted)return true;load.data.value=result;return ['COMPLETED','CANCELLED','REJECTED','RETURN_REJECTED'].includes(result.status)})
onMounted(async()=>{await load.reload();if(alive&&allowed('VIEW_MATERIALS'))await materials.reload()})
onUnmounted(()=>{alive=false;imageController.abort();Object.values(images.value).forEach(URL.revokeObjectURL)})
// 物流事实采用持久幂等键，受理不冒充退款成功；撤销后的状态仍由GET确认。
async function action(name:'cancel'|'return-shipment'){const body=name==='return-shipment'?{...shipment}:undefined;const result=await command.run<Aftersale>(name,body,key=>api(`${url}/${name}`,{method:'POST',body,key}));if(result&&alive){load.data.value=result;notice.value='已收到服务器响应，请查看当前状态。';if(allowed('VIEW_MATERIALS'))await materials.reload();poll.start()}}
// 私有证据通过鉴权Blob读取；页面销毁立即中止并回收所有对象URL。
async function show(key:string){if(images.value[key])return;error.value='';imageBusy.value=key;try{const blob=await apiBlob(`/evidence-files/${pathNo(key)}`,imageController.signal);if(alive&&!imageController.signal.aborted)images.value[key]=URL.createObjectURL(blob)}catch(e){if(alive)error.value=(e as Error).message}finally{if(alive)imageBusy.value=''}}
</script>
<template><section><RouterLink class="back-link" to="/aftersales">← 售后记录</RouterLink><PageHeader title="售后详情" :description="no"><template #actions><button @click="load.reload()">刷新状态</button></template></PageHeader><Feedback :error="load.error.value || command.error.value || error" :loading="load.loading.value || command.busy.value"/><div v-if="load.data.value" class="two-col"><div><article class="panel"><div class="row spread"><h2>申请进度</h2><StatusBadge :status="load.data.value.status"/></div><dl class="details"><dt>关联订单</dt><dd><RouterLink :to="`/orders/${pathNo(load.data.value.orderNo)}`" class="mono wrap">{{load.data.value.orderNo}}</RouterLink></dd><dt>售后类型</dt><dd>{{load.data.value.type==='UNSHIPPED_FULL'?'未发货整单退款':load.data.value.type==='REFUND_ONLY'?'仅退款':'退货退款'}}</dd><dt>申请原因</dt><dd>{{load.data.value.reason}}</dd><dt>退款状态</dt><dd><StatusBadge :status="load.data.value.refundStatus || 'PENDING'"/></dd><dt v-if="load.data.value.refundNo">退款编号</dt><dd v-if="load.data.value.refundNo" class="mono wrap">{{load.data.value.refundNo}}</dd></dl><p v-if="load.data.value.lastError" class="notice">处理提示：{{load.data.value.lastError}}</p></article><article v-if="allowed('VIEW_MATERIALS')" class="panel"><div class="row spread"><h2>申请材料</h2><button @click="materials.reload()">刷新材料</button></div><Feedback :error="materials.error.value" :loading="materials.loading.value"/><template v-if="materials.data.value"><h3>逐件退款分配</h3><div v-for="a in materials.data.value.allocations" :key="`${a.orderItemId}:${a.unitNo}`" class="unit-row">商品项 {{a.orderItemId}} · 第 {{a.unitNo}} 件 <strong>{{money(a.amountCents)}}</strong></div><p v-if="materials.data.value.returnDeadline">退货提交截止：{{time(materials.data.value.returnDeadline)}}</p><div v-if="materials.data.value.shipment" class="shipment"><h3>退货物流</h3><p>{{materials.data.value.shipment.carrier}} · <span class="mono">{{materials.data.value.shipment.trackingNo}}</span></p></div><div v-if="materials.data.value.inspection"><h3>商家验收记录</h3><p>{{materials.data.value.inspection.accepted?'验收通过':'未通过验收'}} · {{materials.data.value.inspection.reason}}</p></div><h3>图片证据</h3><p v-if="!materials.data.value.evidence.length" class="muted">未附图片证据。</p><div class="evidence-grid"><figure v-for="(e,index) in materials.data.value.evidence" :key="e.objectKey"><figcaption>证据 {{index+1}} · {{e.purpose==='APPLICATION'?'申请材料':'验收材料'}}</figcaption><img v-if="images[e.objectKey]" :src="images[e.objectKey]" :alt="`售后证据${index+1}`"/><button v-else :disabled="!!imageBusy" @click="show(e.objectKey)">{{imageBusy===e.objectKey?'读取中…':'查看受控图片'}}</button></figure></div></template></article></div><aside class="panel summary"><span class="eyebrow">申请退款金额</span><strong class="large-price">{{load.data.value.amountCents===null?'确认中':money(load.data.value.amountCents)}}</strong><p role="status">{{notice}}</p><Feedback :error="poll.message.value" :loading="poll.running.value"/><div class="stack"><button :disabled="poll.running.value" @click="poll.start">查询最新进度</button><button v-if="poll.running.value" @click="poll.stop">停止自动查询</button></div><form v-if="allowed('RETURN_SHIPMENT')" @submit.prevent="action('return-shipment')"><h2>登记退货物流</h2><p class="small muted">寄出后填写真实信息，提交后不可更换物流。请留意材料中的截止时间。</p><label for="carrier">承运商</label><input id="carrier" v-model.trim="shipment.carrier" maxlength="80" required/><label for="tracking">退货单号</label><input id="tracking" v-model.trim="shipment.trackingNo" maxlength="80" pattern="[A-Za-z0-9_-]{1,80}" required/><button class="primary full" :disabled="command.busy.value">提交退货物流</button></form><div v-if="allowed('CANCEL')"><p class="small muted">撤销将终止本次申请，请确认后操作。</p><button class="danger-button full" :disabled="command.busy.value" @click="action('cancel')">撤销售后申请</button></div></aside></div></section></template>
